<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$q=db()->prepare('SELECT m.*,s.code,s.name FROM marks m JOIN subjects s ON s.id=m.subject_id JOIN students st ON st.id=m.student_id WHERE st.user_id=? ORDER BY m.id DESC');$q->execute([actor_id()]);page_top('Result Center');?><div class='card p-3 table-responsive'><table class='table'><tr><th>Subject</th><th>Total</th><th>Grade</th><th>Point</th><th>Result</th></tr><?php foreach($q as $r):?><tr><td><?=e($r['code'].' · '.$r['name'])?></td><td><?=e($r['total_marks'])?></td><td><?=e($r['grade'])?></td><td><?=e($r['grade_point'])?></td><td><span class='badge bg-<?=($r['result']==='PASS'?'success':'danger')?>'><?=e($r['result'])?></span></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>